@page{margin:26px 32px}body{font-family:'DejaVu Sans',sans-serif;color:#111;font-size:9.5px;line-height:1.3}table{border-collapse:collapse;width:100%}td,th{border:1px solid #333;padding:3px;vertical-align:top}h1{font-size:11px;text-align:center;margin:6px 0}p{margin:7px 0}.meta td{padding:3px 7px}.criteria th{background:#eee}.criteria tr{page-break-inside:avoid}.signatures td{border:0;text-align:center;width:50%}.signatures img{height:38px;max-width:180px}.signoff{page-break-inside:avoid}.page{page-break-before:always}.evidence{max-width:100%;max-height:330px}.caption{font-size:9px;color:#555}footer{font-size:8px;color:#666;margin-top:10px}